import React from 'react';
import { View, type StyleProp, type ViewStyle } from 'react-native';
import Svg, { G, Path } from 'react-native-svg';
import { useTheme } from '../../contexts/ThemeContext';
import { MARK, WORDMARK } from './logoArt';

/**
 * Brand art (assets/brand/*.svg are the masters, generated by scripts/brand/build-brand.mjs).
 * The ring takes the ink of its ground (ivory on dark, near-black on light); the cross and LINK/SOCIAL are gold.
 * `ground` forces a ground when the logo sits on fixed brand colors (share cards) instead of the theme.
 */
type Ground = 'theme' | 'dark' | 'light';

const BRAND_GOLD = '#C9A84C';
const IVORY = '#F6EFE3';
const INK = '#1C160E';

function useInk(ground: Ground) {
  const t = useTheme();
  if (ground === 'dark') return { ink: IVORY, gold: BRAND_GOLD };
  if (ground === 'light') return { ink: INK, gold: BRAND_GOLD };
  return { ink: t.c.text, gold: t.c.gold };
}

const MARK_PATHS = (ink: string, gold: string) => (
  <>
    <Path d={MARK.ring} fill={ink} />
    <Path d={MARK.bar} fill={gold} />
    <Path d={MARK.stem} fill={gold} />
  </>
);

/** The mark alone. `size` is its height. */
export function LogoMark({ size = 48, ground = 'theme', style }: { size?: number; ground?: Ground; style?: StyleProp<ViewStyle> }) {
  const { ink, gold } = useInk(ground);
  return (
    <View style={style} accessible accessibilityRole="image" accessibilityLabel="Christ Link Social">
      <Svg width={size * MARK.aspect} height={size} viewBox={MARK.viewBox}>
        {MARK_PATHS(ink, gold)}
      </Svg>
    </View>
  );
}

const [VX, VY, , VH] = MARK.viewBox.split(' ').map(Number);
const H_MARK = 199; // lockup units: the mark is 199 tall, the wordmark 128, 36 apart
const W_MARK = H_MARK * MARK.aspect;
const GAP = 36;
const H_GAP = 40;

/**
 * Mark + wordmark. `horizontal`: side by side (headers, share cards). `stacked`: mark centered above (welcome, sign-in).
 * `width` sets the overall width; height follows.
 */
export function Logo({
  layout = 'horizontal',
  width = 240,
  ground = 'theme',
  style,
}: {
  layout?: 'horizontal' | 'stacked';
  width?: number;
  ground?: Ground;
  style?: StyleProp<ViewStyle>;
}) {
  const { ink, gold } = useInk(ground);
  const s = H_MARK / VH;
  const mark = <G transform={`scale(${s}) translate(${-VX} ${-VY})`}>{MARK_PATHS(ink, gold)}</G>;
  const words = (
    <>
      <Path d={WORDMARK.christ} fill={ink} />
      <Path d={WORDMARK.link} fill={gold} />
      <Path d={WORDMARK.social} fill={gold} />
    </>
  );

  if (layout === 'stacked') {
    const W = WORDMARK.width;
    const H = H_MARK + H_GAP + WORDMARK.height;
    return (
      <View style={style} accessible accessibilityRole="image" accessibilityLabel="Christ Link Social">
        <Svg width={width} height={(width * H) / W} viewBox={`0 0 ${W} ${H}`}>
          <G transform={`translate(${(W - W_MARK) / 2} 0)`}>{mark}</G>
          <G transform={`translate(0 ${H_MARK + H_GAP})`}>{words}</G>
        </Svg>
      </View>
    );
  }

  const W = W_MARK + GAP + WORDMARK.width;
  return (
    <View style={style} accessible accessibilityRole="image" accessibilityLabel="Christ Link Social">
      <Svg width={width} height={(width * H_MARK) / W} viewBox={`0 0 ${W} ${H_MARK}`}>
        {mark}
        <G transform={`translate(${W_MARK + GAP} ${(H_MARK - WORDMARK.height) / 2})`}>{words}</G>
      </Svg>
    </View>
  );
}
